def operation(n):
    if n < 0:
        return -1 # Should not happen for positive integers
    if n == 0:
        return 0 # Or handle as per convention, but starting N is positive
    d = n % 10
    a = n // 10
    return a + 3 * d

def generate_sequence(start_n, max_steps=100):
    sequence = [start_n]
    history = {start_n: 0}
    current_n = start_n
    for step in range(1, max_steps + 1):
        current_n = operation(current_n)
        sequence.append(current_n)
        if current_n in history:
            cycle_start_index = history[current_n]
            cycle_length = step - cycle_start_index
            return sequence, cycle_start_index, cycle_length
        history[current_n] = step
    return sequence, None, None

print("--- Analysis for starting values N=1 to N=10 ---")
for n_start in range(1, 11):
    sequence, start_index, length = generate_sequence(n_start)

    if length is not None:
        print(f"\nStarting N={n_start}:")
        print(f"  Sequence segment: {sequence}")
        print(f"  Cycle detected at step {start_index + 1} (value {sequence[start_index]}). Length: {length}")
    else:
        print(f"\nStarting N={n_start}: Sequence generated {len(sequence)} steps without a cycle.")
